function held({ label, boundary, unsupported, diagnostic, systems, parts, citations = ['datasets'] }) {
  return Object.freeze({
    description: `The frozen ${label} identity is broader than the exact Nissan and NHTSA record. ${boundary} ${unsupported}`,
    solution: `${diagnostic} Do not buy ${parts} from this page; the exact failure path, model year, production or DTC branch, and VIN fitment must be established first.`,
    symptoms: ['exact symptom, operating condition and warning state documented', 'model year and DTC or campaign eligibility verified', 'competing failure paths tested before replacement'],
    affectedSystems: systems,
    evidence: [boundary, unsupported, 'No owner-frequency rate, universal retail part or cross-generation mechanism is established.'],
    conflict: `The indexed ${label} title materially exceeds the exact condition, model-year scope or component identity supported by primary evidence.`,
    summary: `Held the overbroad ${label} identity and removed unsupported owner totals, costs, mileage, DTC and replacement claims.`,
    citations,
    commerceDecision: 'failure path, component, generation and VIN fitment remain unresolved; no universal retail part',
  });
}
function retained({ description, solution, symptoms, systems, evidence, summary, parts, citations }) {
  return Object.freeze({
    description,
    solution: `${solution} Do not buy ${parts} from this page; recall or bulletin eligibility and VIN-specific remedy must be confirmed first.`,
    symptoms,
    affectedSystems: systems,
    evidence,
    conflict: null,
    summary,
    citations,
    commerceDecision: 'failure path, component, generation and VIN fitment remain unresolved; no universal retail part',
  });
}

